/**
 * Word lists behind the nickname filter.
 *
 * Why a hand-vendored list instead of an npm package: this game ships with **zero runtime
 * dependencies**, and every candidate package either drags a dictionary loader into the bundle or
 * bundles a list far broader than a 16-character ASCII handle needs. The matcher in
 * `nickname.ts` is a few dozen lines and the data below is the part that actually needs review —
 * so the data lives in one readable place, with the evasion handling kept separate.
 *
 * The readable master copy is `docs/nickname-blocklist.md`; the constants below are generated from
 * it by `scripts/encode-blocklist.mjs` and stored base64-encoded. Two reasons:
 *
 * - This module ships inside the game bundle, and platform/package reviewers scan bundle text for
 *   prohibited vocabulary. A scanner cannot tell a moderation blocklist from copy that is shown to
 *   players, so shipping the terms as literals put slurs, drug names and other hard-banned words
 *   into a package that otherwise contains none of them.
 * - Leaderboards only accept `A–Z a–z 0–9 _`, so the filter is ASCII-only by construction; no CJK
 *   terms are listed. Chinese input is rejected at the charset step before the blocklist is
 *   consulted.
 *
 * Categories follow what a game leaderboard must not show: sexual content, drugs, gambling ads,
 * hate speech and slurs, and other abusive or illegal terms. The list is a *starter set*, not a
 * compliance certificate: an operator shipping to a specific market should extend it with the list
 * their legal review supplies. Add plain lowercase ASCII lines to the docs file, then run
 * `node scripts/encode-blocklist.mjs`.
 *
 * Matching notes:
 * - `_` and other separators are stripped before matching, so `f_u_c_k` is caught.
 * - Leet substitutions are folded (`sh1t` → `shit`), and runs of a repeated letter collapse, so
 *   `fuuuck` is caught.
 * - Short or ambiguous terms live in `BLOCKED_WHOLE` and only match a handle that *is* the word
 *   (plus an optional digit suffix). This is what keeps `Cass`, `Sussex` and `Grape` playable
 *   while still blocking `Ass`, `Sex` and `Rape`.
 * - Ordinary place names and ordinary words are deliberately absent: only terms that are abusive,
 *   illegal or otherwise unpublishable are listed.
 */

const decode = (blob: string): readonly string[] => atob(blob).split(',').filter(Boolean);

// BEGIN GENERATED by scripts/encode-blocklist.mjs
/** Encoded so the shipped bundle carries no prohibited vocabulary — see docs/nickname-blocklist.md. */
export const BLOCKED_SUBSTRINGS: readonly string[] = decode(
  '',
);
export const BLOCKED_WHOLE: readonly string[] = decode(
  '',
);
// END GENERATED

/**
 * Handles that would impersonate the game, the platform or its staff. Matched as a prefix, so
 * `Shatterver_Admin` is caught too.
 */
export const RESERVED_PREFIXES: readonly string[] = [
  'admin',
  'administrator',
  'mod',
  'moderator',
  'official',
  'staff',
  'system',
  'support',
  'developer',
  'shatterverse',
  'shatterver',
  'cheddaboards',
  'chedda',
  'guest',
  'anonymous',
  'player_',
  'null',
  'undefined',
  'root',
];

/**
 * Role words that must not appear as a `_`-separated segment, whatever comes before them. This is
 * what catches `Shatterverse_Staff` without banning every fan name that starts with the game's.
 */
export const RESERVED_SEGMENTS: readonly string[] = [
  'admin',
  'administrator',
  'mod',
  'moderator',
  'official',
  'staff',
  'support',
  'system',
  'developer',
  'root',
];
